DECLARE packs jsonb := $pack$[{"codigo":"S22AP-484-1","legacy_id":484,"version_nucleo":2,"relacionadas":["S22M-C04"],"coberturas":[{"legacy_id":484,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Catálogo físico lf_ops.paises desplegado PR #4816: PE +51 prioritario, activos y orden alfabético; fallback Perú decidido. Sustituye bloqueo histórico por falta de catálogo; binding runtime pendiente."}],"paquete":{"modo":"HEREDA","tipo":"CAMBIO","clase":"PANTALLA","clave":"s22ap_legacy_484_0","dueno":"PRODUCTO","codigo":"S22AP-484-1","efecto":"BLOQUEAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/484","solicitante":"Cristhian / Claude S22-AT"},"titulo":"Prefijo visible +51 en ONB_001","alcance":"CLIENT_ONBOARDING","familia":"FIELDS","impacto":"REVISAR","autoridad":"LEG-PRODUCTO","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ap_onb001_country_selector"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ap_pe_not_first"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ap_other_countries_not_alphabetical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_location_preselection_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_prefix_not_canonical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_chevron_missing_or_wrong_token"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_unregistered_country_option"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_selector_enabled_without_catalog"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_catalog_source_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_inactive_country_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_location_fallback_not_pe"},"der":{"lit":true}}}},"naturaleza":"CONDUCTA","descripcion":"En ONB_001 BLOQUEAR selector cuyo catálogo no se resuelva desde lf_ops.paises, que muestre países inactivos o no ordene activos por es_prioritario DESC, orden_alfabetico ASC. Perú PE primero; preseleccionar país activo según ubicación cuando esté disponible y sea reconocida, en caso contrario fallback Perú PE. Prefijo visible desde prefijo_telefonico del país seleccionado; Perú resuelve +51 desde tabla, no hardcodear prefijo ni inventar opciones. Chevron pequeño visible navy_muted, no azul; selector dropdown permite solo opciones activas registradas. Si catálogo no disponible no habilitar opciones inventadas. No modifica IG ni rasters; binding runtime pendiente.","pruebas":[{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":true,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":true,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":true,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":true,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":true,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":true,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":true,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":true,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":true,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":false,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":true},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; hashes jsonb:='{}'; hash_all text; t record; v integer;
BEGIN
 IF (SELECT count(*) FROM lf_ops.reglas)=586 THEN
 IF NOT EXISTS (SELECT 1 FROM lf_ops.paises WHERE iso2='PE' AND prefijo_telefonico='+51' AND activo AND es_prioritario) OR (SELECT iso2 FROM lf_ops.paises WHERE activo ORDER BY es_prioritario DESC,orden_alfabetico LIMIT 1) IS DISTINCT FROM 'PE' THEN RAISE EXCEPTION 'S22AT_COUNTRY_PREFLIGHT'; END IF;
 END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM v THEN RAISE EXCEPTION 'S22AT_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,v); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=v LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AT_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AT_HASH_ALL %',hash_all;
END $at$;
COMMIT;
